middleware.split_once_colon.code:
fn split_once_colon(s: &[u8]) -> Option<(Vec<u8>, Vec<u8>)> {
    let mut i = 0;
    while i < s.len() {
        if s[i] == b':' {
            let mut a = Vec::new();
            let mut j = 0;
