net.entry_contains.code:
fn entry_contains(network: IpAddr, prefix: u8, ip: IpAddr) -> bool {
    match (network, ip) {
        (IpAddr::V4(n), IpAddr::V4(addr)) => {
            if prefix == 0 {
                return true;
            }
            if prefix >= 32 {
                return n == addr;
            }
            let mask = u32::MAX << (32 - prefix);
            (n & mask) == (addr & mask)
        }
        (IpAddr::V6(n), IpAddr::V6(addr)) => {
            if prefix == 0 {
                return true;
            }
            if prefix >= 128 {
                return n == addr;
            }
            let mask = u128::MAX << (128 - prefix);
            (n & mask) == (addr & mask)
        }
        _ => false,
    }
}

