pub fn resolve_client_ip(peer: IpAddr, xff: Option<IpAddr>, x_real_ip: Option<IpAddr>,
                         trusted_proxies: &TrustedProxies) -> IpAddr {
    if !trusted_proxies.contains(peer) {
        return peer;
    }
    if let Some(ip) = xff {
        return ip;
    }
    if let Some(ip) = x_real_ip {
        return ip;
    }
    peer
}

