fn remove_user_files(files: &[TokenFile], user: &[u8]) -> (Vec<TokenFile>, usize) {
    let mut kept = Vec::new();
    let mut count = 0;
    let mut i = 0;
    while i < files.len() {
        let remove = match &files[i].info {
            Some(info) => bytes_eq(&info.user, user),
